for name, hl in pairs(vim.api.nvim_get_hl(0, {})) do
    local changed = false
    for _, key in ipairs({ "fg", "bg", "sp" }) do
        local role = hl[key] and roles[string.format("#%06x", hl[key])]
        if role then
            hl[key], changed = role, true
        end
    end
    if changed then
        vim.api.nvim_set_hl(0, name, hl)
    end
end
